import{_ as e,o as i,c as a,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Ceph Performance Meeting 2021-09-02","description":"","frontmatter":{"title":"Ceph Performance Meeting 2021-09-02","date":"2021-09-02T00:00:00.000Z","updated":"2021-09-03T00:00:00.000Z","tags":["Ceph","分布式存储","Crimson性能优化","小对象存储方案","CephFS","RBD","RADOS"],"categories":["会议纪要","技术讨论","存储系统"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Performance_Meeting_2021-09-02.md","filePath":"posts/2021/Ceph_Performance_Meeting_2021-09-02.md","lastUpdated":1780459816000}'),r={name:"posts/2021/Ceph_Performance_Meeting_2021-09-02.md"};function o(n,l,s,p,h,u){return i(),a("div",null,[...l[0]||(l[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="关键细节" tabindex="-1">关键细节 <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节&quot;">​</a></h4><ul><li><p><strong>Ceph Crimson 测试更新</strong>：</p><ul><li>通过在多个 OSD 上模拟多反应器环境，解决了之前无法实现的问题。</li><li>测试显示在随机读取时具有良好的扩展性和较低的 CPU 使用率。</li><li>随机写入的扩展性不如预期，需要进一步优化。</li><li>顺序写入在 Crimson 中的表现不如传统 OSD，需要调查原因。</li></ul></li><li><p><strong>数十亿小对象存储方案讨论</strong>：</p><ul><li>软件遗产基金会提出了一个基于 Ceph 的架构，用于存储数十亿小对象。</li><li>方案涉及使用 RBD 图像和外部数据库进行对象索引。</li><li>讨论了使用 Ceph 的 tiering v2 和 RADOS manifest 功能来简化架构的可能性。</li><li>需要评估现有 manifest 功能的稳定性和性能，以及是否支持这种特定用例。</li></ul></li></ul><h4 id="讨论的主要议题" tabindex="-1">讨论的主要议题 <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题&quot;">​</a></h4><ul><li><p><strong>Crimson 性能优化</strong>：</p><ul><li>随机读取的扩展性和 CPU 使用率表现良好。</li><li>随机写入和顺序写入的性能需要进一步优化。</li></ul></li><li><p><strong>小对象存储方案</strong>：</p><ul><li>讨论了使用 Ceph 现有功能与创建新功能的利弊。</li><li>需要评估现有 manifest 功能的稳定性和性能，以及是否支持这种特定用例。</li></ul></li></ul><h4 id="决定的事项" tabindex="-1">决定的事项 <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项&quot;">​</a></h4><ul><li><p><strong>Crimson 优化</strong>：</p><ul><li>继续优化 Crimson 的随机写入和顺序写入性能。</li></ul></li><li><p><strong>小对象存储方案</strong>：</p><ul><li>需要进一步评估和讨论使用 Ceph 现有功能与创建新功能的可行性和性能。</li><li>计划与软件遗产基金会进一步讨论具体需求和方案。</li></ul></li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li><p><strong>Crimson 优化</strong>：</p><ul><li>继续进行性能测试和优化，特别是随机写入和顺序写入。</li></ul></li><li><p><strong>小对象存储方案</strong>：</p><ul><li>与软件遗产基金会进行深入讨论，评估现有 Ceph 功能的适用性。</li><li>如果现有功能不满足需求，考虑开发新的存储方案。</li></ul></li><li><p><strong>会议安排</strong>：</p><ul><li>安排与软件遗产基金会的后续会议，进一步讨论具体需求和方案。</li></ul></li></ul><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h3><p>本次会议主要讨论了 Ceph Crimson 的性能优化和小对象存储方案的可行性。后续将通过进一步的测试和讨论，确定最佳的解决方案，并与相关方进行深入沟通。</p>',11)])])}const c=e(r,[["render",o]]);export{_ as __pageData,c as default};
